/**
 * The seeded story is anchored to a fixed "today" so the demo is identical on any
 * presentation day. All "last N days" windows and rules are computed relative to it.
 * The Automation page can simulate other dates via its date picker.
 */
export const STORY_DATE = "2026-10-31";

/** Days of content/metrics history generated by the mock source. */
export const HISTORY_DAYS = 120;

export const CURRENCY = "THB";

/** Base URL used inside drafted messages (e.g. report links). */
export const APP_URL = process.env.APP_URL ?? "http://localhost:3000";
